
.panel {
  padding: 10px;
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
}

.label {
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--c-text-muted);
}

.count {
  font-family: var(--font-mono);
  font-size: 11px;
  color: var(--c-primary);
}

.empty {
  font-size: 12px;
  color: var(--c-text-muted);
}

.ledger {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
}

.ledger th,
.ledger td {
  padding: 4px 6px;
  border: 1px solid var(--c-border);
  text-align: left;
  vertical-align: top;
}

.ledger th {
  font-size: 11px;
  font-weight: 400;
  color: var(--c-text-muted);
  background: var(--c-surface);
}

.num {
  font-family: var(--font-mono);
  text-align: right;
}

.favor {
  color: var(--c-accent);
}

.strong {
  font-weight: 700;
}

.archive {
  color: var(--c-text-muted);
}
