
.topbar {
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface);
}

.head {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 10px;
  background: none;
  border: none;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
  cursor: pointer;
  text-align: left;
}

.brand {
  font-family: var(--font-mono);
  font-weight: 700;
  letter-spacing: 0.16em;
  color: var(--c-primary);
}

.chip {
  padding: 1px 7px;
  border: 1px solid var(--c-border);
  font-size: 11px;
  letter-spacing: 0.06em;
}

.chip-world {
  color: var(--c-primary);
  border-color: var(--c-primary);
}

.chip-daily {
  color: var(--c-success);
  border-color: var(--c-success);
}

.chip-event {
  color: var(--c-warning);
  border-color: var(--c-warning);
}

.caret {
  margin-left: auto;
  font-size: 11px;
  color: var(--c-text-muted);
}

.meta {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 10px 8px;
  font-size: 11px;
  color: var(--c-text-muted);
}

.readout {
  font-family: var(--font-mono);
  color: var(--c-text);
}

.sep {
  opacity: 0.4;
}

.loc {
  margin-left: auto;
}
