
.hero {
  padding: 10px;
  border-bottom: 1px solid var(--c-border);
  background: var(--c-surface);
}

.identity,
.balance {
  display: flex;
  align-items: center;
  gap: 8px;
}

.balance {
  margin-top: 6px;
}

.label {
  font-size: 11px;
  letter-spacing: 0.08em;
  color: var(--c-text-muted);
}

.chip {
  padding: 1px 7px;
  border: 1px solid var(--c-border);
  font-size: 11px;
}

.identity-text {
  font-size: 12px;
}

.balance-value {
  font-family: var(--font-mono);
  font-size: 26px;
  font-weight: 700;
  color: var(--c-primary);
  line-height: 1.1;
}

.unit {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--c-primary);
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 1px;
  margin-top: 8px;
  background: var(--c-border);
  border: 1px solid var(--c-border);
}

.cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  background: var(--c-bg);
}

.readout {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--c-text);
}

.grade {
  color: var(--c-primary);
  font-weight: 700;
}

.readout-warning {
  color: var(--c-warning);
}

.readout-danger {
  color: var(--c-warning-deep);
  animation: pulse 1.4s ease-in-out infinite;
}

.mark-cell {
  grid-column: 1 / -1;
}

.mark-track {
  height: 10px;
  border: 1px solid var(--c-border);
  background: var(--c-surface);
  overflow: hidden;
}

.mark-fill {
  height: 100%;
  width: 0;
  background: var(--c-accent);
  opacity: 0.55;
  transition:
    width 0.6s ease,
    opacity 0.6s ease,
    box-shadow 0.6s ease;
}

.mark-high {
  opacity: 0.85;
  box-shadow: 0 0 8px var(--c-accent);
}

.mark-full {
  opacity: 1;
  box-shadow: 0 0 14px var(--c-accent);
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }

  50% {
    opacity: 0.45;
  }
}
